#!/usr/bin/env node
/**
 * run-loop-codex-routers — preflight harness for the Codex router generator
 * (plugins/loop/scripts/gen-codex-routers.js): byte-determinism, router set
 * completeness, zero baked paths, config refusal, idempotent writes, and the
 * committed workshop routers matching generated bytes (--check dogfood gate).
 */
'use strict';
const path = require('path');
const fs = require('fs');
const os = require('os');
const { execFileSync } = require('child_process');

const REPO = path.resolve(__dirname, '..', '..');
const GEN_CLI = path.join(REPO, 'plugins', 'loop', 'scripts', 'gen-codex-routers.js');
const GEN = require(GEN_CLI);

let pass = 0, fail = 0; const failures = [];
function ok(label, cond, detail) {
  if (cond) { console.log(`  ok  ${label}`); pass++; }
  else { console.log(`  FAIL  ${label}${detail ? ' — ' + detail : ''}`); failures.push(label); fail++; }
}

// LR-1: generation is byte-deterministic.
{
  const a = GEN.generate();
  const b = GEN.generate();
  ok('LR-1 deterministic bytes', JSON.stringify(a) === JSON.stringify(b));
  ok('LR-1 non-empty', Object.keys(a).length > 0);
}

// LR-2: router set covers exactly the plugin skills, loop- prefixed, in pairs.
{
  const files = GEN.generate();
  const skills = GEN.listPluginSkills().map((s) => s.name);
  const expected = skills.flatMap((n) => [`loop-${n}/SKILL.md`, `loop-${n}/agents/openai.yaml`]).sort();
  ok('LR-2 exact router file set', JSON.stringify(Object.keys(files).sort()) === JSON.stringify(expected));
}

// LR-3: routers bake no paths and carry the frontmatter contract.
{
  const files = GEN.generate();
  const offenders = [];
  for (const [rel, content] of Object.entries(files)) {
    if (/\/Users\/|\/opt\/|notes\/sauce\//.test(content)) offenders.push(rel);
  }
  ok('LR-3 no baked paths', offenders.length === 0, offenders.join(', '));
  for (const [rel, content] of Object.entries(files)) {
    if (!rel.endsWith('SKILL.md')) continue;
    const fm = GEN.parseFrontmatter(content);
    ok(`LR-3 ${rel} frontmatter`, fm && fm.name === rel.split('/')[0] && fm.description.length > 40);
    ok(`LR-3 ${rel} points at plugin_root`, /codex\.plugin_root/.test(content) && /GENERATED/.test(content));
  }
}

// LR-4: CLI refuses without a binding; writes idempotently with one.
{
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'loop-routers-'));
  try {
    let code = 0, body = '';
    try { execFileSync(process.execPath, [GEN_CLI, '--json', '--repo', tmp], { encoding: 'utf8' }); }
    catch (e) { code = e.status; body = String(e.stdout || ''); }
    ok('LR-4 refuses without config', code === 1 && /config_missing/.test(body));

    fs.mkdirSync(path.join(tmp, '.loop'), { recursive: true });
    fs.writeFileSync(path.join(tmp, '.loop', 'config.json'), JSON.stringify({ codex: { routers: true } }));
    const first = JSON.parse(execFileSync(process.execPath, [GEN_CLI, '--json', '--repo', tmp], { encoding: 'utf8' }));
    ok('LR-4 first write generates', first.ok === true && first.no_op === false && first.written.length > 0);
    const second = JSON.parse(execFileSync(process.execPath, [GEN_CLI, '--json', '--repo', tmp], { encoding: 'utf8' }));
    ok('LR-4 second write is no_op', second.ok === true && second.no_op === true);
    const check = JSON.parse(execFileSync(process.execPath, [GEN_CLI, '--json', '--check', '--repo', tmp], { encoding: 'utf8' }));
    ok('LR-4 check passes after write', check.ok === true && check.no_op === true);

    fs.appendFileSync(path.join(tmp, '.agents', 'skills', 'loop-status', 'SKILL.md'), 'drift\n');
    let checkCode = 0, checkBody = '';
    try { execFileSync(process.execPath, [GEN_CLI, '--json', '--check', '--repo', tmp], { encoding: 'utf8' }); }
    catch (e) { checkCode = e.status; checkBody = String(e.stdout || ''); }
    ok('LR-4 check refuses drift', checkCode === 1 && /routers_stale/.test(checkBody));
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

// LR-5: the workshop's committed routers match generated bytes (dogfood gate).
{
  let out = null, code = 0, body = '';
  try { out = JSON.parse(execFileSync(process.execPath, [GEN_CLI, '--json', '--check', '--repo', REPO], { encoding: 'utf8' })); }
  catch (e) { code = e.status; body = String(e.stdout || ''); }
  ok('LR-5 workshop routers current', out && out.ok === true, body.slice(0, 400));
}

console.log(`\n${pass} passed, ${fail} failed`);
if (fail) { console.error('FAILURES:', failures.join(', ')); process.exit(1); }
